rows=[]
for path,main,secondary,intent,opportunity,changes,evidence in items:
 url=DOMAIN+path;p=pages.get(url,{})
 candidates=[k for k in keywords if k['url_propuesta']==url]
 rows.append(dict(url=url,keyword_principal_editorial=main,variantes_seleccionadas=secondary,intencion=intent,prioridad='P1 observada' if p else 'P2 brecha/utilidad verificada',google_periodo=base['gsc']['period'],google_clicks=p.get('clicks',''),google_impressions=p.get('impressions',''),google_ctr=p.get('ctr',''),google_position=p.get('position',''),metrica_pagina_estado='observada' if p else 'URL exacta ausente de exportación; no equivale a cero',oportunidad=opportunity,cambios_implementados=changes,evidencia=evidence,propuestas_keyword_maestro=len(candidates),consulta_url_observada=False,fecha_publicacion='',estado='Implementado local; sin publicación verificada'))
with (OUT/'mapa-implementado-por-url.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
with (OUT/'comparacion-posterior.csv').open('w',encoding='utf-8-sig',newline='') as f:
 cols=['hito_dias_desde_publicacion','buscador','url','publicacion_fecha','periodo_inicio','periodo_fin','pais','dispositivo','tipo_busqueda','clicks','impressions','ctr','position','keywords_observadas','keywords_nuevas','keywords_suben','keywords_bajan','top3','top10','top20','top100','ventana_base_comparable','notas']
 w=csv.DictWriter(f,fieldnames=cols);w.writeheader()
 for days in [7,14,30,60,90]:
  for engine in ['Google Search Console','Bing Webmaster Tools','Semrush MX']:
   for r in rows:w.writerow(dict(hito_dias_desde_publicacion=days,buscador=engine,url=r['url'],notas='Pendiente de publicación y exportación comparable; celdas vacías no son cero.'))
print(json.dumps({'selected_urls':len(rows),'followup_rows':len(rows)*15,'no_measurements_invented':True}))
